-- 此站點的問答（原本寫死在前端 about/colophonQa，技術名稱與文章卡夾在元件裡）。
-- 答案用的小格式：空一行分段、`程式碼`、[文字](網址)、單獨一行的網址是文章卡。
-- 跟 0031 同一個規則：只寫給站名是「宙と木」的站；E2E 的種子會在後端開機後重跑這段 INSERT。
INSERT OR IGNORE INTO page_content (key, value)
SELECT 'qa', '{"intro":{"zh-TW":"此站點是我用來記錄技術與生活的個人網站，從 2025 年 4 月起持續寫到現在。","zh-CN":"此站点是我用来记录技术与生活的个人网站，从 2025 年 4 月起持续写到现在。","en":"This site is my personal corner for jotting down tech and life. It has been growing since April 2025.","ja":"このサイトは技術と生活を書き留めるための個人サイトで、2025 年 4 月から今まで続けています。","ko":"이 사이트는 기술과 일상을 기록하는 개인 웹사이트로, 2025 년 4 월부터 지금까지 계속 써오고 있습니다."},"items":[{"q":{"zh-TW":"建立此站點的初衷？","zh-CN":"建立此站点的初衷？","en":"Why did you build this site?","ja":"このサイトを作った理由は？","ko":"사이트를 만든 이유는?"},"a":{"zh-TW":"最初架設這個網站，是為了在找實習時能有個地方展示自己的技術棧與開發能力。結果找實習時並沒有真正派上用場，反而是現在的同事偶爾會來看我的網站。","zh-CN":"最初架设这个网站，是为了在找实习时能有个地方展示自己的技术栈与开发能力。结果找实习时并没有真正派上用场，反而是现在的同事偶尔会来看我的网站。","en":"Originally I built it to have a place to show my stack and skills while looking for an internship. It didn''t really help with the internship hunt — but my current coworkers do drop by occasionally now.","ja":"最初はインターンを探すときに自分のスタックと開発スキルを見せる場所が欲しくて作りました。結局インターン探しには役に立ちませんでしたが、今は現職の同僚がたまに覗きにきてくれます。","ko":"처음에는 인턴 구할 때 제 스택과 개발 능력을 보여줄 공간이 필요해서 만들었어요. 정작 인턴 찾을 때는 별 도움이 안 됐고, 오히려 지금 동료들이 가끔씩 들러줍니다."}},{"q":{"zh-TW":"網站的技術棧？","zh-CN":"网站的技术栈？","en":"What''s the tech stack?","ja":"技術スタックは？","ko":"기술 스택은?"},"a":{"zh-TW":"前端採用 `React 19` 搭配 `TanStack Start`（SSG/ISR），以 `Vite` 建置、`Tailwind CSS` 處理樣式；太空背景使用 `Three.js`（WebGPU/TSL 管線）渲染。後端已全面改寫為 `Rust`（axum）——Steam、Spotify、WakaTime 與 GitHub 等外部數據也由它串接，資料庫使用 `SQLite`。基礎設施全部透過 `Docker` 進行容器化部署。","zh-CN":"前端采用 `React 19` 搭配 `TanStack Start`（SSG/ISR），以 `Vite` 构建、`Tailwind CSS` 处理样式；太空背景使用 `Three.js`（WebGPU/TSL 管线）渲染。后端已全面改写为 `Rust`（axum）——Steam、Spotify、WakaTime 与 GitHub 等外部数据也由它串接，数据库使用 `SQLite`。基础设施全部通过 `Docker` 进行容器化部署。","en":"The frontend uses `React 19` with `TanStack Start` (SSG/ISR), built with `Vite` and styled with `Tailwind CSS`. The space backdrop renders with `Three.js` (WebGPU/TSL). The backend has been fully rewritten in `Rust` (axum) — still pulling data from Steam, Spotify, WakaTime, GitHub and friends; data lives in `SQLite`. The whole stack is containerised with `Docker`.","ja":"フロントエンドは `React 19` と `TanStack Start`（SSG/ISR）を採用し、`Vite` でビルド、`Tailwind CSS` でスタイリング。宇宙背景は `Three.js`（WebGPU/TSL）で描画しています。バックエンドは `Rust`（axum）に全面書き換え——Steam・Spotify・WakaTime・GitHub などの外部データもここで取得しています。データベースは `SQLite`、インフラはすべて `Docker` でコンテナ化されています。","ko":"프런트엔드는 `React 19` 와 `TanStack Start` (SSG/ISR)를 사용하고, `Vite` 로 빌드, `Tailwind CSS` 로 스타일링합니다. 우주 배경은 `Three.js` (WebGPU/TSL)로 렌더링합니다. 백엔드는 `Rust` (axum)로 전면 재작성했으며 — Steam·Spotify·WakaTime·GitHub 같은 외부 데이터도 여기서 가져옵니다. 데이터베이스는 `SQLite` 를 사용하고, 인프라는 전부 `Docker` 로 컨테이너화되어 있습니다."}},{"q":{"zh-TW":"關於照片牆與 AI 的使用？","zh-CN":"关于照片墙与 AI 的使用？","en":"About the photo wall and AI usage?","ja":"写真ウォールと AI の使い方は？","ko":"사진 월과 AI 활용은?"},"a":{"zh-TW":"站內的照片集使用 Masonry 佈局，並透過自動化腳本提取 EXIF 資訊。後續加入了 AI CLIP Tagger 輔助處理標籤，且上傳圖片時會自動產生 `thumbhash` 作為模糊佔位圖。我會使用 AI 工具協助處理這類瑣碎的自動化流程。詳細可以參考這篇文：\n\nhttps://koimsurai.com/blog/21","zh-CN":"站内的照片集使用 Masonry 布局，并透过自动化脚本提取 EXIF 资讯。后续加入了 AI CLIP Tagger 辅助处理标签，且上传图片时会自动产生 `thumbhash` 作为模糊占位图。我会使用 AI 工具协助处理这类琐碎的自动化流程。详细可以参考这篇文：\n\nhttps://koimsurai.com/blog/21","en":"The photo gallery uses a Masonry layout, with EXIF extracted via automation scripts. I later added an AI CLIP Tagger for tag suggestions, and on upload each image gets a `thumbhash` as a blur-sm placeholder. I lean on AI tools for these tedious automation flows. More details in this post:\n\nhttps://koimsurai.com/blog/21","ja":"サイト内のアルバムは Masonry レイアウトで、EXIF は自動化スクリプトで抽出しています。後から AI CLIP Tagger を追加してタグ付けを補助しており、画像アップロード時には `thumbhash` がぼかしのプレースホルダーとして生成されます。こういう細かい自動化には AI を使っています。詳細はこちらの記事で：\n\nhttps://koimsurai.com/blog/21","ko":"사진첩은 Masonry 레이아웃이고, EXIF는 자동화 스크립트로 추출합니다. 이후 AI CLIP Tagger를 추가해 태그 작업을 보조하며, 이미지 업로드 시 자동으로 `thumbhash` 를 흐림 플레이스홀더로 생성합니다. 이런 자질구레한 자동화에는 AI 도구를 적극적으로 사용해요. 자세한 내용은 이 글에서:\n\nhttps://koimsurai.com/blog/21"}},{"q":{"zh-TW":"這裡有藏彩蛋嗎？","zh-CN":"这里有藏彩蛋吗？","en":"Any easter eggs hidden here?","ja":"ここにイースターエッグはありますか？","ko":"이스터에그가 있나요?"},"a":{"zh-TW":"沒有。沒有實作彩蛋，這裡所見即所得。","zh-CN":"没有。没有实作彩蛋，这里所见即所得。","en":"Nope. No easter eggs implemented — what you see is what you get.","ja":"ありません。仕込んでいないので、見えているそのままです。","ko":"없습니다. 이스터에그는 만들지 않았고, 보이는 그대로입니다."}},{"q":{"zh-TW":"這個網站的主要受眾是誰？","zh-CN":"这个网站的主要受众是谁？","en":"Who is this site for?","ja":"このサイトの主な対象は？","ko":"이 사이트의 주된 대상은?"},"a":{"zh-TW":"最初架這個站，單純是把這裡當作我個人求職使用，沒有特別去社群上宣傳。但說實話，既然我都花這麼多時間弄了，當然還是會希望自己花心血熬夜刻出來的畫面與架構能被人看見。\n\n所以，如果你剛好逛到這裡，覺得這個站點的設計或技術棧還合你的胃口，非常歡迎交換友鏈。也歡迎直接在[留言](/messages)留個足跡。","zh-CN":"最初架这个站，单纯是把这里当作我个人求职使用，没有特别去社群上宣传。但说实话，既然我都花这么多时间弄了，当然还是会希望自己花心血熬夜刻出来的画面与架构能被人看见。\n\n所以，如果你刚好逛到这里，觉得这个站点的设计或技术栈还合你的胃口，非常欢迎交换友链。也欢迎直接在[留言](/messages)留个足迹。","en":"It started as my personal job-hunt site, with no real promotion on social. Honestly though, after pouring this many late nights into it, I do hope the visuals and architecture get to be seen by someone.\n\nSo if you happened to wander in and the design or stack feels right, link exchanges are very welcome. Feel free to leave a footprint on the[messages](/messages)page too.","ja":"最初は個人の就活用サイトとして作り、SNS で宣伝もしていません。とはいえこれだけ時間をかけて作ったので、夜なべして作ったデザインや構造を誰かに見てもらえると嬉しいです。\n\nですので、たまたま辿りついてデザインや技術スタックが気に入ったら、相互リンク大歓迎です。[メッセージ](/messages)ページから足あとを残してくれても嬉しいです。","ko":"원래는 개인 구직용으로 만들었고 따로 SNS에 홍보하지도 않았어요. 하지만 솔직히 이렇게 시간을 들였으니, 밤새워 만든 화면과 구조를 누군가가 봐주면 좋겠다는 마음은 있습니다.\n\n그러니 우연히 들렀다가 디자인이나 스택이 마음에 들면, 상호 링크 환영합니다.[메시지](/messages)페이지에 발자국을 남겨도 좋아요."}},{"q":{"zh-TW":"站點標題「宙と木」是怎麼來的？","zh-CN":"站点标题「宙と木」是怎么来的？","en":"Where does the site title 「宙と木」 come from?","ja":"サイト名「宙と木」はどこから？","ko":"사이트 제목 「宙と木」은 어디서 왔어요?"},"a":{"zh-TW":"沒什麼特別的故事。某天問了 Gemini 一些日文站名候選，看到「宙と木」覺得滿帥的就用了。剛好「宙」（宇宙）跟網站的太空主視覺對得起來，「木」也跟我的網路慣用名「木村盆栽」呼應，就這樣定案了。","zh-CN":"没什么特别的故事。某天问了 Gemini 一些日文站名候选，看到「宙と木」觉得满帅的就用了。刚好「宙」（宇宙）跟网站的太空主视觉对得起来，「木」也跟我的网路惯用名「木村盆栽」呼应，就这样定案了。","en":"Nothing dramatic. One day I asked Gemini for Japanese site-name candidates, saw 「宙と木」 and thought it looked cool. 「宙」(cosmos) matched the space visuals nicely, and 「木」 echoes my online handle 「木村盆栽」, so I went with it.","ja":"特別な物語はありません。ある日 Gemini に日本語のサイト名候補をいくつか聞いて、「宙と木」がいい感じだったのでそのまま使いました。「宙」（宇宙）はサイトの宇宙系ビジュアルと合うし、「木」はネット上のハンドル「木村盆栽」と呼応するので、そのまま決まりました。","ko":"특별한 사연은 없어요. 어느 날 Gemini 에게 일본어 사이트명 후보를 몇 개 받았는데, 「宙と木」이 멋져 보여서 그대로 썼습니다. 「宙」(우주)는 사이트의 우주 비주얼과 맞고, 「木」은 닉네임 「木村盆栽」과 호응해서 자연스럽게 정해졌어요."}},{"q":{"zh-TW":"為什麼叫 Koimsurai？這名字怎麼唸？","zh-CN":"为什么叫 Koimsurai？这名字怎么念？","en":"Why \"Koimsurai\" — how is it pronounced?","ja":"なぜ Koimsurai？読み方は？","ko":"왜 Koimsurai 인가요? 어떻게 읽어요?"},"a":{"zh-TW":"這其實是一個組合字。我在網路上的慣用名是「木村盆栽」（Kimura Bonsai），而 Koimsurai 就是從這兩個詞的羅馬拼音中萃取組合而成的專屬 ID。","zh-CN":"这其实是一个组合字。我在网路上的惯用名是「木村盆栽」（Kimura Bonsai），而 Koimsurai 就是从这两个词的罗马拼音中萃取组合而成的专属 ID。","en":"It''s a compound word. My online handle is 「木村盆栽」 (Kimura Bonsai), and Koimsurai is a custom ID stitched together from the romaji of those two words.","ja":"これは合成語です。ネット上のハンドル名は「木村盆栽」（Kimura Bonsai）で、Koimsurai はその二つのローマ字から抜き出して組み合わせた専用 ID です。","ko":"합성어입니다. 온라인 닉네임은 「木村盆栽」(Kimura Bonsai)이고, Koimsurai 는 그 두 단어의 로마자에서 따와 만든 전용 ID 입니다."}},{"q":{"zh-TW":"那為什麼當初要叫「木村盆栽」？","zh-CN":"那为什么当初要叫「木村盆栽」？","en":"Why \"Kimura Bonsai\" originally?","ja":"では最初に「木村盆栽」と名乗ったのは？","ko":"그럼 왜 처음에 「木村盆栽」이라고 했어요?"},"a":{"zh-TW":"剛開始只是因為很喜歡木村拓哉，就隨意借用了這個姓氏，加上「盆栽」覺得唸起來很順口就用了。","zh-CN":"刚开始只是因为很喜欢木村拓哉，就随意借用了这个姓氏，加上「盆栽」觉得念起来很顺口就用了。","en":"Just because I was a big Kimura Takuya fan and casually borrowed the surname, then tacked on \"bonsai\" because it sounded nice.","ja":"木村拓哉が好きだったので苗字を借りて、「盆栽」を付けたら語呂が良かったので使い始めました。","ko":"키무라 타쿠야를 좋아해서 성씨를 빌리고, 「盆栽」을 붙였더니 발음이 좋아서 그대로 쓰게 됐습니다."}}]}'
WHERE EXISTS (SELECT 1 FROM site_settings WHERE key = 'site' AND json_extract(value, '$.name') = '宙と木');
